// Parse the outer payload (string-or-object).
const raw = $json.payload;
let payload = raw;

if (typeof raw === 'string') {
  try { payload = JSON.parse(raw); } catch { payload = raw; }
}

// Deterministic repair for the #1 cause of invalid tool-arg JSON: an LLM
// emitting RAW control characters (real newlines / tabs) inside a JSON
// string value — e.g. multi-line jsCode or a systemMessage. JSON forbids
// literal control chars inside strings, so JSON.parse throws. We walk the
// string tracking whether we're inside a string literal (respecting
// backslash escapes) and escape only the control chars that sit INSIDE a
// string. Structural whitespace between tokens is left untouched. Fully
// deterministic and idempotent on already-valid JSON.
function repairJsonControlChars(s) {
  let out = '';
  let inStr = false;
  let esc = false;
  for (let i = 0; i < s.length; i++) {
    const ch = s[i];
    const code = s.charCodeAt(i);
    if (esc) { out += ch; esc = false; continue; }
    if (ch === '\\') { out += ch; esc = true; continue; }
    if (ch === '"') { inStr = !inStr; out += ch; continue; }
    if (inStr && code < 0x20) {
      if (ch === '\n') out += '\\n';
      else if (ch === '\r') out += '\\r';
      else if (ch === '\t') out += '\\t';
      else if (ch === '\b') out += '\\b';
      else if (ch === '\f') out += '\\f';
      else out += '\\u' + code.toString(16).padStart(4, '0');
      continue;
    }
    out += ch;
  }
  return out;
}

// Deep-parse nested JSON-string fields. The MCP transport delivers
// object-shaped tool args as JSON-stringified strings, so for fields
// that are supposed to be objects/arrays we parse them here once.
// Idempotent: already-parsed objects pass through unchanged.
// On a parse failure we attempt a single deterministic control-char
// repair before giving up (then fall back to the raw value, unchanged
// behaviour, so this can never regress a payload that parses today).
function deepParse(value) {
  if (typeof value !== 'string') return value;
  const trimmed = value.trim();
  if (!trimmed) return value;
  try {
    return JSON.parse(trimmed);
  } catch {
    try {
      return JSON.parse(repairJsonControlChars(trimmed));
    } catch {
      return value;
    }
  }
}

if (payload && typeof payload === 'object' && !Array.isArray(payload)) {
  if ('updates'      in payload) payload.updates      = deepParse(payload.updates);
  if ('body'         in payload) payload.body         = deepParse(payload.body);
  if ('node_payload' in payload) payload.node_payload = deepParse(payload.node_payload);
  if ('connect_to'   in payload) payload.connect_to   = deepParse(payload.connect_to);
  if ('disconnect'   in payload) payload.disconnect   = deepParse(payload.disconnect);
}

return { ...$json, payload };

// Merge, de-dupe and rank the per-keyword search hits into a smart result list.
// The HTTP node ran once per probe (keyword x case-variant); collect every hit,
// de-dupe by workflow id, then score each candidate against the lowercased
// keyword tokens so multi-keyword / word-order-independent queries rank well.

const httpItems = $('Search Workflow By Name').all();
const meta = $('Build Search Queries').first().json;
const scoreTokens = Array.isArray(meta.scoreTokens) ? meta.scoreTokens : [];
const rawQuery = meta.rawQuery ?? '';
const phrase = scoreTokens.join(' ');

// Collect unique candidate workflows by id (defensive: HTTP errors / empties).
const byId = new Map();
for (const it of httpItems) {
  const data = it && it.json ? it.json.data : null;
  if (!Array.isArray(data)) continue;
  for (const wf of data) {
    if (wf && wf.id != null && !byId.has(wf.id)) byId.set(wf.id, wf);
  }
}

function escapeRe(s) {
  return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function scoreWorkflow(wf) {
  const nameLc = String(wf.name ?? '').toLowerCase();
  if (scoreTokens.length === 0) return 1;
  let matched = 0;
  let wholeWord = 0;
  for (const t of scoreTokens) {
    if (!t) continue;
    if (nameLc.includes(t)) {
      matched++;
      const re = new RegExp('(^|[^a-z0-9])' + escapeRe(t) + '($|[^a-z0-9])');
      if (re.test(nameLc)) wholeWord++;
    }
  }
  if (matched === 0) return 0;
  let score = matched * 10 + wholeWord * 3;
  if (matched === scoreTokens.length) score += 50; // all keywords present
  if (phrase && nameLc.includes(phrase)) score += 40; // contiguous phrase
  return score;
}

let ranked = [...byId.values()]
  .map((wf) => ({ wf, score: scoreWorkflow(wf) }))
  .filter((x) => x.score > 0)
  .sort(
    (a, b) =>
      b.score - a.score ||
      String(a.wf.name).length - String(b.wf.name).length ||
      String(b.wf.updatedAt).localeCompare(String(a.wf.updatedAt)),
  )
  .slice(0, 25);

if (ranked.length === 0) {
  return [
    {
      json: {
        message: `No workflows matched "${rawQuery}".`,
        query: rawQuery,
        count: 0,
      },
    },
  ];
}

return ranked.map(({ wf, score }) => ({
  json: {
    id: wf.id,
    name: wf.name,
    active: wf.active ?? null,
    tags: Array.isArray(wf.tags)
      ? wf.tags.map((t) => (t && t.name ? t.name : t))
      : [],
    updatedAt: wf.updatedAt ?? null,
    _score: score,
  },
}));

const targetNode = $('Parse Payload').first().json?.payload?.node_name;

if (!targetNode) {
  throw new Error("Missing payload.node_name in 'Parse Payload'.");
}

const nodes = $json.nodes

if (!Array.isArray(nodes)) {
  throw new Error("workflowData.nodes not found on $json.");
}

const nodeItem = nodes.find(n => n?.name === targetNode) || null;

if (!nodeItem) {
  const available = nodes.map(n => n?.name).filter(Boolean);
  throw new Error(
    `Node not found in workflowData.nodes: "${targetNode}". Available: ${available.slice(0, 50).join(", ")}`
  );
}

return nodeItem;

// The n8n public POST /workflows endpoint rejects read-only fields.
// We strip them defensively and ensure required fields have safe defaults.
const raw = $('Parse Payload').first().json.payload;
const wf = typeof raw === 'string' ? JSON.parse(raw) : raw;

if (!wf || typeof wf !== 'object') throw new Error('payload must be an object describing a workflow');
if (!wf.name) throw new Error('payload.name is required');
if (!Array.isArray(wf.nodes)) throw new Error('payload.nodes must be an array');

const {
  id, active, tags, shared, pinData, versionId, meta, triggerCount,
  createdAt, updatedAt,
  ...clean
} = wf;

return {
  name: clean.name,
  nodes: clean.nodes,
  connections: clean.connections ?? {},
  settings: clean.settings ?? { executionOrder: 'v1' },
  ...(clean.staticData ? { staticData: clean.staticData } : {}),
};

const targetNode = $('Parse Payload').first().json?.payload?.node_name;

if (!targetNode) {
  throw new Error("Missing payload.node_name in 'Parse Payload'.");
}

const executionHistory = $json.executionHistory;

if (!Array.isArray(executionHistory)) {
  throw new Error("executionHistory not found on $json.");
}

const nodeExecution = executionHistory.find(entry => entry?.node === targetNode) || null;

if (!nodeExecution) {
  const available = executionHistory.map(entry => entry?.node).filter(Boolean);
  throw new Error(
    `Node not found in executionHistory: "${targetNode}". Available (nodes that ran): ${available.slice(0, 50).join(", ")}`
  );
}

return { ...nodeExecution };

const ALLOWED_SETTINGS = ['saveExecutionProgress','saveManualExecutions','saveDataErrorExecution','saveDataSuccessExecution','executionTimeout','errorWorkflow','timezone','executionOrder','callerPolicy','callerIds','timeSavedPerExecution'];
function sanitizeSettings(s) {
  if (!s || typeof s !== 'object') return { executionOrder: 'v1' };
  const out = {};
  for (const k of ALLOWED_SETTINGS) if (k in s) out[k] = s[k];
  if (!out.executionOrder) out.executionOrder = 'v1';
  return out;
}

const ALLOWED_NODE_KEYS = new Set(['id','name','type','typeVersion','position','parameters','credentials','disabled','notes','notesInFlow','executeOnce','retryOnFail','maxTries','waitBetweenTries','onError','webhookId','alwaysOutputData','continueOnFail','color']);
function sanitizeNode(node) {
  const clean = {};
  for (const k of Object.keys(node)) {
    if (ALLOWED_NODE_KEYS.has(k)) clean[k] = node[k];
  }
  return clean;
}

// n8n connections shape: connections[fromName][type][outputIndex] = [{ node, type, index }, ...]
function mergeEdges(connections, edges) {
  const out = JSON.parse(JSON.stringify(connections ?? {}));
  for (const edge of edges) {
    if (!edge || !edge.from || !edge.to) continue;
    const type = edge.type || 'main';
    const outputIndex = edge.outputIndex ?? 0;
    const inputIndex  = edge.inputIndex  ?? 0;
    out[edge.from] ??= {};
    out[edge.from][type] ??= [];
    while (out[edge.from][type].length <= outputIndex) out[edge.from][type].push([]);
    out[edge.from][type][outputIndex].push({ node: edge.to, type, index: inputIndex });
  }
  return out;
}

// Remove edges matching { from, to, type? }. inputIndex is ignored on match —
// callers usually don't track it. If multiple matching edges exist on the same
// outputIndex bucket, they're all removed.
function removeEdges(connections, edges) {
  const out = JSON.parse(JSON.stringify(connections ?? {}));
  for (const edge of edges) {
    if (!edge || !edge.from || !edge.to) continue;
    const type = edge.type || 'main';
    if (!out[edge.from] || !out[edge.from][type]) continue;
    out[edge.from][type] = out[edge.from][type].map(
      bucket => bucket.filter(c => !(c.node === edge.to && (c.type ?? 'main') === type))
    );
    // Tidy: if every outputIndex bucket is empty, drop the type. Then if empty, drop the from key.
    if (out[edge.from][type].every(b => b.length === 0)) delete out[edge.from][type];
    if (Object.keys(out[edge.from]).length === 0) delete out[edge.from];
  }
  return out;
}

const parsed         = $('Parse Payload').first().json.payload;
const newNode        = parsed.node_payload;
const edgesToAdd     = Array.isArray(parsed.connect_to) ? parsed.connect_to : [];
const edgesToRemove  = Array.isArray(parsed.disconnect) ? parsed.disconnect : [];
const workflow       = $json;

const hasNewNode = newNode && typeof newNode === 'object' && !Array.isArray(newNode)
  && typeof newNode.name === 'string' && newNode.name.trim() !== ''
  && typeof newNode.type === 'string' && newNode.type.trim() !== '';

const nodes        = hasNewNode ? [...workflow.nodes, newNode] : [...workflow.nodes];
// Order: remove first, then add. Lets a caller swap an edge in one call.
const afterRemove  = removeEdges(workflow.connections, edgesToRemove);
const connections  = mergeEdges(afterRemove, edgesToAdd);

const out = {
  name: workflow.name,
  nodes: nodes.map(sanitizeNode),
  connections,
  settings: sanitizeSettings(workflow.settings),
};
if (workflow.staticData) out.staticData = workflow.staticData;
return out;

const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow not found, malformed node payload, missing required node fields, invalid typeVersion.' };
}
return { success: true, id: r.id, name: r.name, active: r.active, updatedAt: r.updatedAt };

// Surface n8n public API errors instead of swallowing them.
// n8n response shapes:
//   success → full workflow object with `id`
//   error   → { message: '...' } with no `id`
const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow not found, missing credentials on nodes, no schedulable trigger to activate, unsupported top-level fields (id/active/tags/pinData), invalid node typeVersion.' };
}
return { success: true, id: r.id, name: r.name, active: r.active, updatedAt: r.updatedAt };

const r = $json || {};
if (r.message && !r.id && r.message !== 'OK') {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow not found, workflow currently active (deactivate first).' };
}
return { success: true, message: r.id ? `Workflow ${r.id} deleted` : 'Workflow deleted' };

const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow has no schedulable trigger (manual triggers do not count), missing credentials on nodes, workflow not found.' };
}
return { success: true, id: r.id, name: r.name, active: r.active };

const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow not found.' };
}
return { success: true, id: r.id, name: r.name, active: r.active };

const ALLOWED_SETTINGS = ['saveExecutionProgress','saveManualExecutions','saveDataErrorExecution','saveDataSuccessExecution','executionTimeout','errorWorkflow','timezone','executionOrder','callerPolicy','callerIds','timeSavedPerExecution'];
function sanitizeSettings(s) {
  if (!s || typeof s !== 'object') return { executionOrder: 'v1' };
  const out = {};
  for (const k of ALLOWED_SETTINGS) if (k in s) out[k] = s[k];
  if (!out.executionOrder) out.executionOrder = 'v1';
  return out;
}

const ALLOWED_NODE_KEYS = new Set(['id','name','type','typeVersion','position','parameters','credentials','disabled','notes','notesInFlow','executeOnce','retryOnFail','maxTries','waitBetweenTries','onError','webhookId','alwaysOutputData','continueOnFail','color']);
function sanitizeNode(node) {
  const clean = {};
  for (const k of Object.keys(node)) {
    if (ALLOWED_NODE_KEYS.has(k)) clean[k] = node[k];
  }
  return clean;
}

function deepMerge(target, source) {
  const result = { ...target };
  for (const key of Object.keys(source)) {
    if (
      source[key] && typeof source[key] === 'object' && !Array.isArray(source[key]) &&
      target[key] && typeof target[key] === 'object' && !Array.isArray(target[key])
    ) {
      result[key] = deepMerge(target[key], source[key]);
    } else {
      result[key] = source[key];
    }
  }
  return result;
}

const payload = $('Parse Payload').first().json.payload;
const targetName = payload.node_name;
const updates = payload.updates;
const workflow = $json;

if (!targetName) throw new Error('Missing payload.node_name');
if (!updates || typeof updates !== 'object') throw new Error('Missing or invalid payload.updates');

const nodeIndex = workflow.nodes.findIndex(n => n.name === targetName);
if (nodeIndex === -1) {
  const available = workflow.nodes.map(n => n.name).join(', ');
  throw new Error(`Node "${targetName}" not found. Available: ${available}`);
}

const node = workflow.nodes[nodeIndex];
for (const [key, value] of Object.entries(updates)) {
  if (key === 'parameters' && typeof value === 'object' && typeof node.parameters === 'object') {
    node.parameters = deepMerge(node.parameters, value);
  } else {
    node[key] = value;
  }
}
workflow.nodes[nodeIndex] = node;

const out = {
  name: workflow.name,
  nodes: workflow.nodes.map(sanitizeNode),
  connections: workflow.connections ?? {},
  settings: sanitizeSettings(workflow.settings),
};
if (workflow.staticData) out.staticData = workflow.staticData;
return out;

const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow or node not found, missing credentials on existing nodes, invalid update payload.' };
}
return { success: true, message: r.id ? `Node updated in workflow ${r.id}` : 'Node updated', updatedAt: r.updatedAt };

const ALLOWED_SETTINGS = ['saveExecutionProgress','saveManualExecutions','saveDataErrorExecution','saveDataSuccessExecution','executionTimeout','errorWorkflow','timezone','executionOrder','callerPolicy','callerIds','timeSavedPerExecution'];
function sanitizeSettings(s) {
  if (!s || typeof s !== 'object') return { executionOrder: 'v1' };
  const out = {};
  for (const k of ALLOWED_SETTINGS) if (k in s) out[k] = s[k];
  if (!out.executionOrder) out.executionOrder = 'v1';
  return out;
}

const ALLOWED_NODE_KEYS = new Set(['id','name','type','typeVersion','position','parameters','credentials','disabled','notes','notesInFlow','executeOnce','retryOnFail','maxTries','waitBetweenTries','onError','webhookId','alwaysOutputData','continueOnFail','color']);
function sanitizeNode(node) {
  const clean = {};
  for (const k of Object.keys(node)) {
    if (ALLOWED_NODE_KEYS.has(k)) clean[k] = node[k];
  }
  return clean;
}

const payload = $('Parse Payload').first().json.payload;
const targetName = payload.node_name;
const workflow = $json;

if (!targetName) throw new Error('Missing payload.node_name');

const nodeIndex = workflow.nodes.findIndex(n => n.name === targetName);
if (nodeIndex === -1) {
  const available = workflow.nodes.map(n => n.name).join(', ');
  throw new Error(`Node "${targetName}" not found. Available: ${available}`);
}

workflow.nodes.splice(nodeIndex, 1);

const connections = workflow.connections ?? {};
delete connections[targetName];

for (const [sourceName, outputs] of Object.entries(connections)) {
  if (!outputs.main) continue;
  for (let i = 0; i < outputs.main.length; i++) {
    if (!Array.isArray(outputs.main[i])) continue;
    outputs.main[i] = outputs.main[i].filter(conn => conn.node !== targetName);
  }
}

const out = {
  name: workflow.name,
  nodes: workflow.nodes.map(sanitizeNode),
  connections,
  settings: sanitizeSettings(workflow.settings),
};
if (workflow.staticData) out.staticData = workflow.staticData;
return out;

const r = $json || {};
if (r.message && !r.id) {
  return { success: false, error: r.message, description: r.description || '', hint: 'Common causes: workflow or node not found.' };
}
return { success: true, message: r.id ? `Node removed from workflow ${r.id}` : 'Node removed', updatedAt: r.updatedAt };

