parameters.jsCode:
// Build a set of small, case-variant name probes from the search payload.
// WHY: the n8n public API `/workflows?name=` filter is a CASE-SENSITIVE,
// contiguous-substring match. A naive single query (e.g. "universal") misses
// "Universal contact-finder" and can't handle multiple keywords or word order.
// Fetching all ~400 workflows to filter locally is ~100MB, so instead we probe
// each keyword in a few casings and let the HTTP node fan out. Only matching
// workflows come back -> light payloads. Ranking happens downstream.

const raw = String($input.first().json.payload ?? '').trim();

const STOP = new Set([
  'the', 'a', 'an', 'of', 'to', 'and', 'or', 'for', 'in', 'on', 'with',
  'workflow', 'workflows', 'n8n',
]);

// Tokenize on any non-alphanumeric separator; drop tiny tokens and stopwords.
let tokens = raw
  .split(/[^A-Za-z0-9]+/)
  .map((t) => t.trim())
  .filter((t) => t.length >= 2 && !STOP.has(t.toLowerCase()));

// De-dupe tokens case-insensitively, preserve order, cap to 6.
const seen = new Set();
tokens = tokens
  .filter((t) => {
    const k = t.toLowerCase();
    if (seen.has(k)) return false;
    seen.add(k);
    return true;
  })
  .slice(0, 6);

// Lowercased tokens are what the ranking node scores against.
const scoreTokens = tokens.map((t) => t.toLowerCase());

// Probe each token; for 2-4 token queries also probe the joined phrase so an
// exact-ish phrase match can be found and boosted.
const probes = [...tokens];
if (tokens.length >= 2 && tokens.length <= 4) probes.push(tokens.join(' '));

// Fallback: query was only stopwords/symbols -> probe the raw string.
if (probes.length === 0 && raw) probes.push(raw);

// Case variants defeat the API's case-sensitive matching: lower, UPPER, Title,
// and Capitalized-first cover lowercase / ALLCAPS / TitleCase naming.
function variants(s) {
  const lower = s.toLowerCase();
  const upper = s.toUpperCase();
  const title = lower.replace(/\b\w/g, (c) => c.toUpperCase());
  const capFirst = lower.charAt(0).toUpperCase() + lower.slice(1);
  return [...new Set([s, lower, upper, title, capFirst])];
}

const queries = new Set();
for (const p of probes) {
  for (const v of variants(p)) {
    const q = v.trim();
    if (q) queries.add(q);
  }
}

let list = [...queries].filter(Boolean);

// Never send an empty name (would match every workflow = huge payload).
if (list.length === 0) list.push('__no_match__');

return list.map((q) => ({ json: { q, scoreTokens, rawQuery: raw } }));

// Which execution to retry: the caller's explicit execution_id, else the latest one.
const payload = $('Parse Payload').first().json.payload || {};
const data = Array.isArray($input.first().json.data) ? $input.first().json.data : [];

const provided = String(payload.execution_id ?? '').trim();
const latest = data.length ? data[0].id : null;
const execution_id = provided || latest;

if (!execution_id) {
  throw new Error(
    'No execution found to retry for workflow "' + (payload.workflow_id || '') + '". ' +
    'Run that workflow once first, or pass execution_id.'
  );
}

return [{ json: { workflow_id: payload.workflow_id, execution_id: String(execution_id) } }];

// Shape the tool result for the calling agent.
const picked = $('Pick Execution To Retry').first().json;

return [{ json: {
  ok: true,
  workflow_id: picked.workflow_id,
  retried_execution_id: picked.execution_id,
  retry_response: $input.first().json,
  message: 'Re-ran workflow ' + picked.workflow_id + ' by retrying execution ' +
           picked.execution_id + ' with loadWorkflow=true (the current saved definition runs).'
} }];

