// agnostic to the source.
const __raw = $json.data;
const __parsed = typeof __raw === "string"
  ? (() => { try { return JSON.parse(__raw); } catch { return {}; } })()
  : (__raw || {});

const exec = __parsed.resultData || {};
const runs = exec.runData || {};
const stack = (__parsed.executionData?.nodeExecutionStack || []).reduce((m, s) => {
  if (s?.node?.id) m.byId[s.node.id] = s;
  if (s?.node?.name) m.byName[s.node.name] = s;
  return m;
}, { byId: {}, byName: {} });

// ============ config ============
const PREVIEW_CLIP = 1000; // easy to tweak

const first = a => (Array.isArray(a) && a[0] ? a[0] : null);
const firstDeep = a => (Array.isArray(a) && a[0] && Array.isArray(a[0]) && a[0][0] ? a[0][0] : null);

const tryParse = v => {
  if (typeof v !== "string") return v;
  try { return JSON.parse(v); } catch { return v; }
};

const pick = (o, ks) => {
  if (!o || typeof o !== "object") return o;
  const out = {};
  for (const k of ks) if (k in o) out[k] = o[k];
  return out;
};

const shortVal = v => {
  if (v == null) return v;
  if (typeof v === "string") return v.length > 400 ? v.slice(0, 400) + "…" : v;
  if (Array.isArray(v)) return v.slice(0, 10).map(shortVal);
  if (typeof v === "object") {
    const o = {};
    for (const k of Object.keys(v).slice(0, 20)) o[k] = shortVal(v[k]);
    return o;
  }
  return v;
};

const toStr = v => {
  try { return JSON.stringify(v) ?? "null"; } catch { return "\"[unserializable]\""; }
};
const clip = (v, len = PREVIEW_CLIP) => toStr(v).slice(0, len);

const extract = c => {
  if (!c) return null;
  const main = c.main || c.data?.main;
  if (main) {
    const n = firstDeep(main);
    return n?.json ?? n ?? null; // [[[{ json }]]]
  }
  const tool = c.ai_tool;
  if (tool) return (first(tool)?.json ?? first(tool)) ?? null;
  const llm = c.ai_languageModel;
  if (llm) return (first(llm)?.json ?? first(llm)) ?? null;
  const mem = c.ai_memory;
  if (mem) return (first(mem)?.json ?? first(mem)) ?? null;
  return c.json || null;
};

const shapeIO = x => {
  if (!x) return x;
  if (x.binary && typeof x.binary === "object") {
    x = { ...x, binary: Object.keys(x.binary) }; // collapse binary keys
  }
  if (x.headers || x.body || x.params || x.query || x.webhookUrl) {
    return {
      body: x.body || null,
      query: x.query || null,
      params: x.params || null,
      headers: x.headers ? pick(x.headers, ["host", "content-type", "accept", "user-agent", "cf-ipcountry", "x-forwarded-for"]) : null,
      webhookUrl: x.webhookUrl || null,
      executionMode: x.executionMode || null
    };
  }
  if (x.stocks || x.output_instructions) {
    return { stocks: tryParse(x.stocks) ?? x.stocks, note: x.output_instructions || null };
  }
  return x;
};

const parseErrResponse = msgs => {
  if (!Array.isArray(msgs) || !msgs[0]) return undefined;
  const s = String(msgs[0]);
  const m = s.match(/-\s+"(.+)"$/);
  if (!m) return s.slice(0, 300);
  const raw = m[1].replace(/\\"/g, '"');
  const parsed = tryParse(raw);
  return typeof parsed === "string" ? parsed.slice(0, 300) : parsed;
};

// map workflow nodes by name to fetch unrendered parameters + type
const wfNodesByName = {};
for (const n of ($json.workflowData?.nodes || [])) {
  if (n?.name) wfNodesByName[n.name] = n;
}

// 1) Collect rows with raw input/output + error if available
const rawRows = Object.entries(runs).flatMap(([node, arr]) =>
  arr.map(r => {
    const nodeId = r.error?.node?.id;
    const stk = (nodeId && stack.byId[nodeId]) || stack.byName[node] || null;

    const inputRaw =
      extract(r.inputOverride || {}) ||
      extract(stk?.data || {}) ||
      null;

    const outputRaw = extract(r.data || {}) || null;

    const err = r.error
      ? shortVal({
          name: r.error.name,
          httpCode: r.error.httpCode,
          message: r.error.message,
          description: r.error.description,
          request: r.error.context?.request ? pick(r.error.context.request, ["method", "uri", "body"]) : undefined,
          response: parseErrResponse(r.error.messages)
        })
      : null;

    return {
      node,
      index: r.executionIndex ?? null,
      status: r.executionStatus,
      ms: r.executionTime ?? null,
      from: r.source && r.source[0] ? r.source[0].previousNode : null,
      rawInput: inputRaw,
      rawOutput: outputRaw,
      errorRaw: err,
    };
  })
