// 2) Backfill input from previous node's output if missing
const prevMap = {};
for (const row of rawRows) {
  if (!prevMap[row.node]) prevMap[row.node] = [];
  prevMap[row.node].push(row);
}
for (const row of rawRows) {
  if (row.rawInput == null && row.from) {
    const prevList = prevMap[row.from] || [];
    let prev = null;
    for (let i = prevList.length - 1; i >= 0; i--) {
      const cand = prevList[i];
      if ((cand.index ?? -1) < (row.index ?? 1e9)) { prev = cand; break; }
    }
    if (prev && prev.rawOutput != null) row.rawInput = prev.rawOutput;
  }
}

// 3) Finalize execution history with full parameters
const executionHistory = rawRows.map(r => {
  const input_preview = shortVal(shapeIO(tryParse(r.rawInput)));
  const output_preview = shortVal(shapeIO(tryParse(r.rawOutput)));
  const nodeMeta = wfNodesByName[r.node] || null;

  return {
    node: r.node,
    type: nodeMeta?.type ?? null,
    index: r.index,
    status: r.status,
    ms: r.ms,
    from: r.from,
    parameters: shortVal(nodeMeta?.parameters ?? null),
    input_preview: clip(input_preview),
    output_preview: clip(output_preview),
    error: clip(r.errorRaw),
  };
});

return { executionHistory };

